/** Page structures from the supplied concept; all cards link to real generated files. */
import { MONTH_SLUGS, monthNumberToName, resolvePlanningYear, buildMonthGrid, schoolYearOverviewAssetPaths, schoolYearStartYear, type SeoMeta } from "@freshcalendars/engine";
import { breadcrumbNavHtml, esc, iconHtml, siteSearchHtml } from "@freshcalendars/site-chrome";
import { STUDIO_STYLES, studioAssets } from "./studio.js";
import { studioDisplaySrcset } from "./previews.js";
import { YEARLY_VARIANTS, BLANK_VARIANTS, WEEKLY_VARIANTS } from "./catalog.js";

const json = (value: unknown) => JSON.stringify(value).replaceAll("<", "\\u003c");
const smallDownload = (href: string, format: string) => `<a href="${esc(href)}" download class="file-chip">${iconHtml(format === "PDF" ? "pdf" : "image")}${format}</a>`;
/** Rendered width of the main studio preview: 420/430/540 px tall boxes, letter ratio (design.ts). */
export const STUDIO_MAIN_SIZES = "(max-width:640px) 325px, (max-width:1023px) 333px, 417px";
/**
 * Month pages show the studio WebPs (the 784 KB PNG was the phone LCP); other pages keep their PNG.
 * onerror falls back to the PNG while a server has the new HTML but not yet the new /assets files.
 */
function mainImageAttrs(studioPng: string | null, png: string): string {
  if (!studioPng) return `src="${esc(png)}"`;
  const d = studioDisplaySrcset(studioPng);
  return `src="${d.src}" srcset="${d.srcset}" sizes="${STUDIO_MAIN_SIZES}" onerror="if(this.srcset){this.removeAttribute('srcset');this.src=this.getAttribute('src').replace(/-1100\\.webp$/,'.png')}"`;
}
export function homeConceptHero(today: Date): string {
  const y = resolvePlanningYear(today);
  const month = today.getMonth() + 1;
  const grid = ["S", "M", "T", "W", "T", "F", "S"].map(d => `<b>${d}</b>`).join("") + buildMonthGrid({ year: y, month: 1 }).weeks.flat().map(c => `<span>${c?.day ?? ""}</span>`).join("");
  const categories = [
    ["year", "Yearly<br>Calendars", "/printable-calendars.html", "green"],
    ["calendar", "Monthly<br>Calendars", "/monthly-calendars/", "blue"],
    ["holiday", "Holiday<br>Calendars", "/holidays/", "orange"],
    ["planner", "Planner<br>Templates", "/printable-weekly-calendar.html", "purple"],
    ["school", "School<br>Calendars", "/printable-school-calendar.html", "blue"],
    ["news", "News &amp;<br>Tips", "/news/", "pink"],
    ["tools", "All Tools", "/calendar-tools/", "green"],
  ];
  return `<section class="home-hero"><img class="hero-photograph" src="/img/design/planning-lake-v1.webp" width="1920" height="640" alt="" fetchpriority="high"><div class="concept-wrap hero-copy"><p class="overline">Free printable calendars</p><h1>Plan Brighter Days<br> with FreshCalendars</h1><p class="hero-intro">Beautiful calendars, holiday dates and planning tools<br class="desktop-break"> for work, school and everyday life.</p>${siteSearchHtml(today, true)}<nav class="category-launchers" aria-label="Explore Fresh Calendars">${categories.map(([icon, label, href, color]) => `<a href="${href}" class="tone-${color}">${iconHtml(icon!)}<span>${label}</span></a>`).join("")}</nav></div><div class="hero-handwriting" aria-hidden="true">Free<br>Print<br>Achieve<br>Repeat<span></span></div><a class="hero-paper" href="/printable-calendars.html" aria-label="View ${y} yearly calendar"><strong>${y}</strong><span class="hero-mini-months">${grid}</span><small>FRESHCALENDARS</small></a></section>`;
}
export function homeCalendarShelf(today: Date): string {
  const y = resolvePlanningYear(today), m = today.getMonth() + 1;
  const month = studioAssets(y, m), floral = studioAssets(y, m, "floral"), planner = studioAssets(y, m, "notes-planner");
  const schoolStart = schoolYearStartYear(today), school = schoolYearOverviewAssetPaths(schoolStart);
  const cards = [
    { title: `${y} Calendar (Yearly)`, href: "/printable-calendars.html", png: `/assets/studio/yearly/${y}/minimal/calendar.png`, pdf: `/assets/studio/yearly/${y}/minimal/calendar.pdf`, tags: `yearly ${y}` },
    { title: `${monthNumberToName(m)} ${y} Calendar`, href: `/${MONTH_SLUGS[m - 1]}-calendars.html`, ...month, tags: `monthly ${y}` },
    { title: `${schoolStart}–${schoolStart + 1} Academic Calendar`, href: "/printable-school-calendar.html", png: school.png, pdf: school.pdf, tags: `school ${y}` },
    { title: `${y} Holiday Calendar`, href: "/holidays/", png: `/assets/${y}/yearly/holidays/calendar.png`, pdf: `/assets/${y}/yearly/holidays/calendar.pdf`, tags: `holidays yearly ${y}` },
    { title: "Monthly Planner", href: `/${MONTH_SLUGS[m - 1]}-calendars.html?style=notes-planner&year=${y}`, ...planner, tags: `planners monthly ${y}` },
    { title: "Blank Calendar", href: "/blank-calendars.html", png: "/assets/blank/classic/calendar.png", pdf: "/assets/blank/classic/calendar.pdf", tags: "blank" },
    { title: `${y + 1} Yearly Calendar`, href: "/printable-yearly-calendar.html", png: `/assets/${y + 1}/yearly/classic/calendar.png`, pdf: `/assets/${y + 1}/yearly/classic/calendar.pdf`, tags: `yearly ${y + 1}` },
  ];
  return `<section class="concept-wrap popular-calendars" data-shelf><div class="shelf-heading"><h2>Popular Printable Calendars</h2><div class="shelf-filters" role="group" aria-label="Filter popular calendars">${[[String(y), String(y)], [String(y + 1), String(y + 1)], ["monthly", "Monthly"], ["yearly", "Yearly"], ["holidays", "Holidays"], ["planners", "Planners"], ["school", "School"], ["blank", "Blank"], ["all", "All"]].map(([id, label]) => `<button data-shelf-filter="${id}" aria-pressed="${id === "all"}">${label}</button>`).join("")}</div><a href="/calendars/">View all →</a></div><div class="calendar-shelf">${cards.map(c => `<article class="shelf-card" data-shelf-card data-tags="${c.tags}"><a href="${c.href}" class="shelf-preview"><img src="${"preview" in c ? c.preview : c.png.replace("calendar.png", "calendar-preview.webp")}" alt="${esc(c.title)}" width="220" height="285" loading="lazy"></a><h3><a href="${c.href}">${esc(c.title)}</a></h3><div class="file-chips">${smallDownload(c.pdf, "PDF")}${smallDownload(c.png, "PNG")}</div></article>`).join("")}</div><button class="shelf-next" data-shelf-next aria-label="Show more calendars">${iconHtml("arrow")}</button></section>`;
}
export function calendarStudio(meta: SeoMeta, lead: string, selection: {year?: number; month?: number; start?: "monday" | "sunday"} = {}): string {
  const year = selection.year ?? meta.calendar.year ?? new Date().getFullYear(), month = selection.month ?? meta.calendar.month;
  const styles: {id:string;label:string;description:string;pdf?:string;png?:string}[] = month ? STUDIO_STYLES.map(s => ({...s})) : (meta.variants?.length ? meta.variants.map(v => ({ id: v.id, label: v.shortLabel, description: v.description, pdf: v.pdf, png: v.png })) : [{ id: "classic", label: "Classic", description: "Free printable calendar", pdf: meta.download.pdf, png: meta.download.png }]);
  if (meta.calendar.family === "yearly") {
    styles.unshift(...["minimal", "floral"].map(id => ({ id, label: id === "minimal" ? "Minimal" : "Floral", description: "Year at a glance", png: `/assets/studio/yearly/${year}/${id}/calendar.png`, pdf: `/assets/studio/yearly/${year}/${id}/calendar.pdf` })));
  }
  const initial = month ? studioAssets(year, month, "scenic", "letter", selection.start ?? "sunday") : { png: "png" in styles[0]! ? styles[0]!.png : meta.download.png, pdf: "pdf" in styles[0]! ? styles[0]!.pdf : meta.download.pdf };
  const monthName = month ? monthNumberToName(month) : "";
  const description = month ? `Download and print this free ${monthName} calendar in PDF or PNG format. Choose your preferred design, paper size and start day.` : lead;
  const model = { dated: !!month || (meta.calendar.year !== null && meta.pageId !== "guide-weekly"), defaultStart: selection.start ?? "sunday", year, month, monthName, lead: description, baseTitle: meta.title.split("|")[0]!.trim(), crumb: meta.breadcrumbs.at(-1)!.name, years: month || meta.calendar.family === "yearly" ? Array.from({length:5},(_,i)=>resolvePlanningYear()+i) : [year], styles };
  const choice = (kind: string, value: string, label: string, selected = false) => `<button type="button" data-choice="${kind}" data-value="${value}" aria-pressed="${selected}">${label}</button>`;
  return `<section class="concept-wrap calendar-detail" data-studio><script type="application/json" data-studio-model>${json(model)}</script>${breadcrumbNavHtml(meta.breadcrumbs, " data-studio-crumb")}<div class="studio-columns"><div class="studio-visual"><div class="studio-preview"><button class="preview-arrow previous" data-style-step="-1" aria-label="Previous design">${iconHtml("arrow")}</button><img data-main-preview ${mainImageAttrs(month ? initial.png : null, initial.png)} alt="${esc(model.baseTitle)}" width="1100" height="1424" fetchpriority="high"><button class="preview-arrow next" data-style-step="1" aria-label="Next design">${iconHtml("arrow")}</button></div><div class="studio-thumbnails" aria-label="Choose a calendar design">${styles.map((s, i) => `<button type="button" data-choice="style" data-value="${s.id}" aria-pressed="${i === 0}" aria-label="${esc(s.label)} design"><img data-style-thumb="${s.id}" src="${month ? studioAssets(year, month, s.id).preview : "png" in s ? s.png : initial.png}" alt="${esc(s.label)}" width="90" height="115" loading="lazy"></button>`).join("")}</div><div class="studio-style-tabs">${styles.map((s, i) => choice("style", s.id, esc(s.label), i === 0)).join("")}</div></div><div class="studio-options"><h1 data-studio-title>${esc(month ? `${monthName} ${year} Calendar (Free Printable)` : model.baseTitle)}</h1><p data-studio-description>${esc(description)}</p><div class="studio-field" ${model.dated ? "" : "hidden"}><label for="studio-year">Calendar year</label><select id="studio-year" data-studio-year>${model.years.map(y => `<option value="${y}" ${y === year ? "selected" : ""}>${y}</option>`).join("")}</select></div><fieldset><legend>File format</legend><div class="option-row">${choice("format", "pdf", "PDF", true)}${choice("format", "png", "PNG")}</div></fieldset><fieldset><legend>Paper size</legend><div class="option-row">${choice("paper", "letter", "Letter (8.5″ × 11″)", true)}${choice("paper", "a4", "A4 (210 × 297 mm)")}</div></fieldset>${month ? `<fieldset><legend>Start day</legend><div class="option-row">${choice("start", "sunday", iconHtml("calendar") + "Sunday", true)}${choice("start", "monday", "Monday")}</div></fieldset>` : ""}<p class="format-note" data-format-note>PDF · US Letter · Sunday start</p><a class="studio-primary" data-primary-download href="${initial.pdf}" download>${iconHtml("download")}<span data-primary-label>Download PDF</span></a><a class="studio-secondary" data-download-format="png" href="${initial.png}" download>${iconHtml("download")}<span data-secondary-label>Download PNG</span></a><div class="studio-actions"><a data-download-format="pdf" href="${initial.pdf}" target="_blank" rel="noopener">${iconHtml("print")}Print PDF</a><button type="button" data-favorite aria-pressed="false">${iconHtml("heart")}<span>Add to favorites</span></button><button type="button" data-calendar-share>${iconHtml("share")}Share</button></div><p class="studio-status" data-studio-status role="status"></p></div></div><div class="download-benefits">${[["download", "Free to download", "and print"], ["check", "High quality", "PDF & PNG"], ["pdf", "A4 and Letter", "sizes included"], ["school", "Perfect for home,", "school and work"]].map(([icon, title, sub]) => `<div>${iconHtml(icon!)}<p><strong>${title}</strong><span>${sub}</span></p></div>`).join("")}</div></section>`;
}

function librarySidebar(year: number, current: string) {
  return `<aside class="library-sidebar"><nav aria-label="Calendar categories">${[["tools", "All Calendars", "/calendars/", "all"], ["year", "Yearly Calendars", "/calendars/?family=yearly", "yearly"], ["calendar", "Monthly Calendars", "/monthly-calendars/", "monthly"], ["holiday", "Holiday Calendars", "/holidays/", "holidays"], ["school", "Academic Calendars", "/printable-school-calendar.html", "school"], ["planner", "Planner Templates", "/calendars/?family=weekly", "weekly"], ["calendar", "Blank Calendars", "/calendars/?family=blank", "blank"], ["planner", "Weekly Planners", "/printable-weekly-calendar.html", "weekly-page"], ["tools", "Calendar Tools", "/calendar-tools/", "tools"]].map(([icon, title, href, id]) => `<a href="${href}" data-library-family="${id}" ${id === current ? 'aria-current="page"' : ""}>${iconHtml(icon!)}${title}</a>`).join("")}</nav><h3>Year</h3><nav aria-label="Calendar years">${Array.from({length:5},(_,i)=>year+i).map(y => `<a href="/monthly-calendars/?year=${y}" data-library-year="${y}">· &nbsp; ${y}</a>`).join("")}</nav></aside>`;
}
export function calendarLibrary(today: Date, monthly: boolean): string {
  const year = resolvePlanningYear(today), years = Array.from({length:5},(_,i)=>year+i);
  const cards: { title: string; family: string; year?: number; month?: number; href: string; png: string; pdf: string; preview: string; style?: string }[] = [];
  for (const y of years) for (let m = 1; m <= 12; m++) { const style = m >= 2 && m <= 5 ? "floral" : "scenic", f = studioAssets(y, m, style); cards.push({ title: `${monthNumberToName(m)} ${y}`, year: y, month: m, family: "monthly", href: `/${MONTH_SLUGS[m - 1]}-calendars.html`, ...f, style }); }
  if (!monthly) {
    for (const y of years) for (const v of YEARLY_VARIANTS) cards.push({ title: `${y} ${v.shortLabel} Calendar`, year: y, family: "yearly", href: y === year ? "/printable-calendars.html" : "/printable-yearly-calendar.html", style: v.id, png: `/assets/${y}/yearly/${v.id}/calendar.png`, pdf: `/assets/${y}/yearly/${v.id}/calendar.pdf`, preview: `/assets/${y}/yearly/${v.id}/calendar-preview.webp` });
    for (const [family, variants, href] of [["blank", BLANK_VARIANTS, "/blank-calendars.html"], ["weekly", WEEKLY_VARIANTS, "/printable-weekly-calendar.html"]] as const) for (const v of variants) cards.push({ title: `${v.label} ${family === "blank" ? "Calendar" : "Planner"}`, family, href, style: v.id, png: `/assets/${family}/${v.id}/calendar.png`, pdf: `/assets/${family}/${v.id}/calendar.pdf`, preview: `/assets/${family}/${v.id}/calendar-preview.webp` });
  }
  return `<div class="concept-wrap library-layout">${librarySidebar(year, monthly ? "monthly" : "all")}<section class="library-main" data-library data-family="${monthly ? "monthly" : "all"}" data-year="${year}">${breadcrumbNavHtml(monthly ? [{ name: "Home", url: "/" }, { name: "Calendars", url: "/calendars/" }, { name: "Monthly Calendars", url: "/monthly-calendars/" }] : [{ name: "Home", url: "/" }, { name: "Calendars", url: "/calendars/" }], " data-library-crumb")}<h1>${monthly ? "Monthly Calendars" : "Printable Calendars"} ${year}</h1><p class="library-intro" data-library-intro>Free printable calendars for ${year}. Download in PDF or PNG format. Choose your design, paper size and start day.</p><div class="library-toolbar"><label><span class="sr-only">Design</span><select name="design"><option value="all">All Designs</option>${STUDIO_STYLES.map(s => `<option value="${s.id}">${s.label}</option>`).join("")}</select></label><label><span class="sr-only">Month</span><select name="month"><option value="">All Months</option>${MONTH_SLUGS.map((_, i) => `<option value="${i + 1}">${monthNumberToName(i + 1)}</option>`).join("")}</select></label><label><span class="sr-only">Paper size</span><select name="paper"><option value="letter">Letter</option><option value="a4">A4</option></select></label><label><span class="sr-only">Start day</span><select name="start"><option value="sunday">Sunday Start</option><option value="monday">Monday Start</option></select></label><label><span class="sr-only">Year</span><select name="year">${years.map(y => `<option>${y}</option>`).join("")}</select></label><button type="button" data-library-reset>Reset filters</button></div><label class="library-search">${iconHtml("search")}<input name="library-search" type="search" placeholder="Find a calendar…"></label><p class="library-count" data-library-count aria-live="polite"></p><div class="library-grid">${cards.map(c => `<article class="library-card" data-library-card data-family="${c.family}" data-year="${c.year ?? ""}" data-month="${c.month ?? ""}" data-default-style="${c.style ?? ""}" data-href="${c.href}" data-pdf="${c.pdf}"><a href="${c.href}" data-card-open><img src="${c.preview}" alt="${esc(c.title)} printable calendar" width="500" height="647" loading="lazy"><h2>${esc(c.title)}</h2></a><div class="file-chips"><a href="${c.pdf}" download data-card-pdf class="file-chip">${iconHtml("pdf")}PDF</a><a href="${c.png}" download data-card-png class="file-chip">${iconHtml("image")}PNG</a></div></article>`).join("")}</div><p data-library-empty hidden>No calendars match these filters. Try another month or design.</p></section></div>`;
}
export function calendarTools(today: Date): string {
  const date = `${today.getFullYear()}-${String(today.getMonth() + 1).padStart(2, "0")}-${String(today.getDate()).padStart(2, "0")}`;
  return `<section class="concept-wrap tools-page"><nav class="concept-breadcrumb"><a href="/">Home</a><span>›</span><span>Calendar Tools</span></nav><h1>Calendar Tools</h1><p>Simple date tools for your next plan.</p><div class="date-tools"><form data-date-tool="between"><h2>Days between dates</h2><label>Start date<input name="from" type="date" value="${date}" required></label><label>End date<input name="to" type="date" required></label><button class="studio-primary">Calculate days</button><output aria-live="polite"></output></form><form data-date-tool="add"><h2>Add or subtract days</h2><label>Start date<input name="from" type="date" value="${date}" required></label><label>Number of days<input name="days" type="number" value="30" step="1" required></label><button class="studio-primary">Find the date</button><output aria-live="polite"></output></form></div><p><a href="/print-guide.html">Printing guide</a> · <a href="/monthly-calendars/">Monthly calendars</a> · <a href="/holidays/">Holiday dates</a></p></section>`;
}
